SELECT ticker, name, current_price_usd, ROUND(per, 1) AS per, ROUND(ps_ratio, 2) AS ps_ratio, ROUND(net_margin * 100, 1) AS net_margin_pct,
       ROUND(operating_margin * 100, 1) AS operating_margin_pct, market_cap_bn_usd
FROM m_screener_us
WHERE per > 0 AND per <= {{max_per}}
  AND net_margin >= {{min_net_margin_pct}} / 100
  AND market_cap_bn_usd >= {{min_mcap_bn}}
ORDER BY per ASC
LIMIT {{limit}}

SELECT ticker, name, ROUND(composite_score, 1) AS composite_score, ROUND(value_score, 1) AS value_score, ROUND(quality_score, 1) AS quality_score,
       current_price_usd, ROUND(pbr, 2) AS pbr, ROUND(roe * 100, 1) AS roe_pct, ROUND(rsi14, 0) AS rsi14
FROM m_screener_us
WHERE composite_score >= {{min_score}}
ORDER BY composite_score DESC
LIMIT {{limit}}

SELECT ticker, name, industry, market_cap_bn_usd,
       ROUND(roic * 100, 1) AS roic_pct, roic_tax_basis, ROUND(ev_ebitda, 1) AS ev_ebitda,
       ROUND(operating_margin * 100, 1) AS operating_margin_pct, ROUND(per, 1) AS per
FROM m_screener_us
WHERE roic >= {{min_roic_pct}} / 100 AND ev_ebitda > 0 AND ev_ebitda <= {{max_ev_ebitda}}
  AND market_cap_bn_usd >= {{min_mcap_bn}}
ORDER BY roic / ev_ebitda DESC
LIMIT {{limit}}

SELECT ticker, name, industry, market_cap_bn_usd,
       f_score, f_score_items, ROUND(interest_coverage, 1) AS interest_coverage, ROUND(current_ratio, 2) AS current_ratio,
       ROUND(accrual_ratio * 100, 1) AS accrual_pct, ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr
FROM m_screener_us
WHERE f_score >= {{min_f_score}} AND current_ratio >= {{min_current_ratio}}
  AND (interest_coverage IS NULL OR interest_coverage >= {{min_icr}})
  AND market_cap_bn_usd >= {{min_mcap_bn}}
ORDER BY f_score DESC, per ASC
LIMIT {{limit}}
